<script setup lang="ts">
import { CheckCircle, Clock3, LoaderCircle, LockKeyhole, Mail, MessageCircle, Phone, Plus } from 'lucide-vue-next'
const config=useRuntimeConfig();const route=useRoute();const {list}=useProperties();const {buildTelLink,number:phone}=usePhone();const {buildUrl}=useWhatsApp();const phoneLink=computed(()=>buildTelLink());const whatsappLink=computed(()=>buildUrl());const email=computed(()=>config.public.email);const {data:properties}=useAsyncData('contact-properties',()=>list());const submitting=ref(false);const submitted=ref(false);const errorMessage=ref('');
const form=reactive({name:'',phone:'',email:'',reason:'',property_id:'',message:'',consent:false});const selectedProperty=computed(()=>properties.value?.find(item=>item.id===form.property_id));const trustPoints=['Clear guidance on current property options','Transparent pricing and payment-plan information','Site inspections available for active properties'];const faqs=[{question:'Can I book a physical site inspection?',answer:'Yes. Select “Book Site Inspection” to choose an active property and preferred date. Our team will contact you to confirm the visit.'},{question:'Can I ask about payment plans before choosing a property?',answer:'Yes. Tell us your preferred location and budget, and an advisor can explain the currently published options.'},{question:'What should I prepare before buying land?',answer:'Review the property information, inspect the site, confirm current pricing and documentation, and complete appropriate independent due diligence before making payment.'},{question:'How quickly will someone respond?',answer:'WhatsApp is usually the fastest channel during office hours. Form enquiries are sent to the sales lead system for follow-up.'}];
function attribution(){const query=route.query;return{utm_source:String(query.utm_source||'')||null,utm_medium:String(query.utm_medium||'')||null,utm_campaign:String(query.utm_campaign||'')||null,utm_content:String(query.utm_content||'')||null,page_url:import.meta.client?window.location.href:null,referrer:import.meta.client?document.referrer||null:null}}
