async function submit(){errorMessage.value='';submitting.value=true;try{const property=selectedProperty.value;const message=[`Enquiry type: ${form.reason}`,form.message].filter(Boolean).join('\n\n');const {error}=await useSupabase().from('leads').insert({name:form.name,phone:form.phone,email:form.email||null,message,property_id:property?.id||null,property_name:property?.name||null,property_location:property?.location_name||null,property_price:property?.price_display||null,source:'contact_page',...attribution()});if(error)throw error;submitted.value=true;track('lead_submitted')}catch(error){console.error(error);errorMessage.value='We could not send your enquiry right now. Please call us or continue on WhatsApp.'}finally{submitting.value=false}}
function resetForm(){Object.assign(form,{name:'',phone:'',email:'',reason:'',property_id:'',message:'',consent:false});submitted.value=false}
